WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, session_start_flag, session_id FROM sessions_transactions ORDER BY txn_type NULLS LAST, txn_time DESC;
